BEGIN;
SELECT no_plan();
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims', '{"sub":"b2222222-2222-4222-8222-222222222222","role":"authenticated"}', true);
SELECT lives_ok($$SELECT api.save_patient_anthropometric_revision(NULL,'f1111111-1111-4111-8111-111111111111',CURRENT_DATE-1,'{"weightKg":72.5}','Consulta')$$, 'Assigned professional can save');
SELECT set_config('test.revision', (SELECT id::text FROM api.professional_patient_anthropometry WHERE patient_id='f1111111-1111-4111-8111-111111111111' ORDER BY created_at DESC LIMIT 1),true);
SELECT is((SELECT recorded_on FROM api.professional_patient_anthropometry WHERE id=current_setting('test.revision')::uuid), CURRENT_DATE-1, 'Date is preserved');
SELECT lives_ok($$SELECT api.save_patient_anthropometric_revision(current_setting('test.revision')::uuid,'f1111111-1111-4111-8111-111111111111',CURRENT_DATE-2,'{"weightKg":73}','Corregida')$$, 'Edit persists');
SELECT is((SELECT values->>'weightKg' FROM api.professional_patient_anthropometry WHERE id=current_setting('test.revision')::uuid),'73','Value updated');
SELECT throws_ok($$SELECT api.save_patient_anthropometric_revision(NULL,'f1111111-1111-4111-8111-111111111111',CURRENT_DATE+1,'{"weightKg":73}')$$, NULL,NULL,'Future dates rejected');
SELECT throws_ok($$SELECT api.save_patient_anthropometric_revision(NULL,'f1111111-1111-4111-8111-111111111111',CURRENT_DATE,NULL)$$, NULL,NULL,'Null values rejected');
SELECT throws_ok($$SELECT api.save_patient_anthropometric_revision(NULL,'f1111111-1111-4111-8111-111111111111',CURRENT_DATE,'{"weightKg":"bad"}')$$, NULL,NULL,'Text rejected');
SELECT throws_ok($$SELECT api.save_patient_anthropometric_revision(NULL,'f1111111-1111-4111-8111-111111111111',CURRENT_DATE,'{"bodyFatPercentage":101}')$$, NULL,NULL,'Invalid percentage rejected');
SELECT throws_ok($$SELECT api.save_patient_anthropometric_revision(NULL,'f4444444-4444-4444-8444-444444444444',CURRENT_DATE,'{"weightKg":73}')$$, NULL,NULL,'Cross tenant write denied');
SELECT throws_ok($$SELECT api.save_patient_anthropometric_revision(NULL,'f3333333-3333-4333-8333-333333333333',CURRENT_DATE,'{"weightKg":73}')$$, NULL,NULL,'Unassigned same tenant denied');
SELECT set_config('test.field',api.save_anthropometric_field('11111111-1111-4111-8111-111111111111',NULL,'Prueba brazo','cm',0)::text,true);
SELECT lives_ok($$SELECT api.save_patient_anthropometric_revision(current_setting('test.revision')::uuid,'f1111111-1111-4111-8111-111111111111',CURRENT_DATE,jsonb_build_object(current_setting('test.field'),25))$$,'Custom field accepted');
SELECT lives_ok($$SELECT api.save_anthropometric_field('11111111-1111-4111-8111-111111111111',current_setting('test.field')::uuid,'Prueba brazo','cm',0,'archived')$$,'Archive field');
SELECT is((SELECT values->>current_setting('test.field') FROM api.professional_patient_anthropometry WHERE id=current_setting('test.revision')::uuid),'25','Archive preserves history');
SELECT throws_ok($$SELECT api.save_patient_anthropometric_revision(NULL,'f1111111-1111-4111-8111-111111111111',CURRENT_DATE,jsonb_build_object(current_setting('test.field'),25))$$,NULL,NULL,'Archived field not accepted in new revision');
SELECT lives_ok($$SELECT api.save_patient_anthropometric_revision(current_setting('test.revision')::uuid,'f1111111-1111-4111-8111-111111111111',CURRENT_DATE,jsonb_build_object(current_setting('test.field'),26))$$,'Existing archived value editable');
SELECT ok(NOT has_table_privilege('authenticated','app.patient_anthropometric_revisions','INSERT'),'No direct DML');
SELECT ok(NOT has_function_privilege('anon','api.save_patient_anthropometric_revision(uuid,uuid,date,jsonb,text)','EXECUTE'),'Anonymous RPC denied');
SELECT set_config('request.jwt.claims', '{"sub":"b3333333-3333-4333-8333-333333333333","role":"authenticated"}', true);
SELECT is((SELECT count(*) FROM api.professional_patient_anthropometry WHERE id=current_setting('test.revision')::uuid),0::bigint,'Other professional cannot read');
SELECT throws_ok($$SELECT api.delete_patient_anthropometric_revision(current_setting('test.revision')::uuid)$$,NULL,NULL,'Other professional cannot delete');
SELECT set_config('request.jwt.claims', '{"sub":"b1111111-1111-4111-8111-111111111111","role":"authenticated"}', true);
SELECT is((SELECT count(*) FROM api.professional_patient_anthropometry),0::bigint,'Nonclinical owner cannot read');
SELECT set_config('request.jwt.claims', '{"sub":"b4444444-4444-4444-8444-444444444444","role":"authenticated"}', true);
SELECT is((SELECT count(*) FROM api.professional_patient_anthropometry),0::bigint,'Assistant cannot read');
SELECT set_config('request.jwt.claims', '{"sub":"d1111111-1111-4111-8111-111111111111","role":"authenticated"}', true);
SELECT is((SELECT count(*) FROM api.professional_patient_anthropometry),0::bigint,'Patient cannot read professional revisions');
SELECT set_config('request.jwt.claims', '{"sub":"a0000000-0000-4000-8000-000000000000","role":"authenticated"}', true);
SELECT is((SELECT count(*) FROM api.professional_patient_anthropometry),0::bigint,'Platform admin cannot read');
SELECT set_config('request.jwt.claims', '{"sub":"b2222222-2222-4222-8222-222222222222","role":"authenticated"}', true);
SELECT lives_ok($$SELECT api.delete_patient_anthropometric_revision(current_setting('test.revision')::uuid)$$,'Author can delete');
SELECT is((SELECT count(*) FROM api.professional_patient_anthropometry WHERE id=current_setting('test.revision')::uuid),0::bigint,'Deletion persisted');
SELECT * FROM finish();
ROLLBACK;
